// CSD_RATIONALE_BEGIN
// Attempt 67 (52.0%) root-cause analysis: The `parser.IsCompletePrefix` check
// at the TOP of the Phase 3 loop breaks generation immediately after the model
// produces the shortest grammatically-valid SQL fragment (e.g. "SELECT id FROM
// highschooler"). This pre-empts any WHERE/JOIN/ORDER BY the model would have
// added, because the break fires BEFORE asking the model for the next token.
// Failing rollouts confirm: "SELECT id FROM high>>" vs correct
// "SELECT id FROM highschooler WHERE name = 'Kyle'".
//
// Single targeted fix: remove the IsCompletePrefix early break from Phase 3.
// Let ConstrainedStep run until the model generates EOS or the 300-step budget
// is exhausted. With hard parser masking, the only valid continuations after a
// complete SQL are grammar-legal extensions (WHERE, JOIN, ORDER BY…) or EOS.
// The model, prompted correctly, will pick EOS only after a complete answer.
//
// Second change: update guidance to explicitly enumerate SQL completeness
// patterns (WHERE filters, JOIN for multi-table, GROUP BY aggregation,
// ORDER BY LIMIT 1 for ranking, INTERSECT/EXCEPT for set ops).
//
// All other structure identical to attempt 67 (best baseline 53.3% = attempt 66):
// Phase 1: ≤5 unconstrained preamble steps.
// Phase 2: Force OpenConstrainedSpan if not already inside.
// Phase 3: ConstrainedStep loop, 300-step budget, NO IsCompletePrefix break.
// Phase 4: CloseConstrainedSpan if complete, else CloseSpanWithinBudget(120).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (unconstrained loop): Guard requires !insideConstrainedOut, so the
//   implication is vacuous throughout. The only true-flip is via RenderedEndsWith;
//   at that point currentConstrainedOut := [] and IsValidPrefix([]) holds by the
//   method precondition. EOS break leaves insideConstrainedOut false (vacuous).
//
// Phase 2 (OpenConstrainedSpan): Runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds.
//
// Phase 3 (ConstrainedStep loop, no IsCompletePrefix break):
//   ConstrainedStep postcondition guarantees next == eosToken OR
//   IsTokenValidNext(parser, currentConstrainedOut, next) holds.
//   EOS branch: break, currentConstrainedOut unchanged (invariant trivially holds
//   since we had it before).
//   Valid-token branch: AppendConstrainedToken postcondition guarantees
//   parser.IsValidPrefix(currentConstrainedOut + [next]), re-establishing
//   the invariant with the new currentConstrainedOut.
//   Invalid-token branch (valid == false): currentConstrainedOut unchanged;
//   invariant trivially preserved. Loop exit preserves whatever holds at break.
//
// Phase 4a (CloseConstrainedSpan): Sets insideConstrainedOut := false, making
//   the implication vacuously true; clears currentConstrainedOut := [].
// Phase 4b (CloseSpanWithinBudget): Its postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each iteration increments steps by 1 (UnconstrainedStep cost +1)
//   and appends 0 (EOS) or 1 (non-EOS) token to generated. Preserved each iter.
//
// Phase 2: OpenConstrainedSpan +1 step, appends exactly 1 "<<" token. 1:1 bound.
//
// Phase 3: Inner invariant |generated| <= |generatedPrefix| + steps + sqlSteps
//   is maintained because each iteration increments sqlSteps by 1 (ConstrainedStep
//   cost +1) and appends at most 1 token (EOS appends 0, valid appends 1,
//   invalid appends 0). After the inner loop, steps := steps + sqlSteps re-
//   establishes the outer invariant. Cap sqlBudget := min(remaining-1, 300)
//   ensures sqlBudget <= maxSteps - old_steps - 1, so new_steps <= maxSteps.
//
// Phase 4a: CloseConstrainedSpan +1 step, appends at most 1 ">>" token. ≤1:1.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated|
//   + closeBudget; steps := steps + closeBudget. Preserved by transitivity.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a COMPLETE SQL SELECT statement that fully answers the question. Rules: (1) Use WHERE for filter conditions like name='X' or age>N. (2) Use JOIN ... ON for queries involving multiple tables. (3) Use GROUP BY with COUNT/SUM/AVG for aggregation. (4) Use ORDER BY ... DESC/ASC LIMIT 1 for max/min/most/highest/lowest. (5) Use INTERSECT or EXCEPT for 'both'/'and also'/'but not' queries. (6) Use DISTINCT when asked for unique values. (7) Use ONLY exact table and column names from the schema. Do not stop at SELECT ... FROM alone.");

var steps: nat := 0;

// Phase 1: Short preamble (≤5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside a constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL via ConstrainedStep loop.
// KEY CHANGE from attempt 67: NO parser.IsCompletePrefix early break.
// The model continues until EOS or budget, enabling WHERE/JOIN/ORDER BY
// generation after the initial SELECT...FROM fragment.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var sqlBudget: nat;
  if remaining <= 1 {
    sqlBudget := 0;
  } else if remaining - 1 <= 300 {
    sqlBudget := remaining - 1;
  } else {
    sqlBudget := 300;
  }

  // stablePrefix = generated[..|generated| - |currentConstrainedOut|]
  // AppendConstrainedToken grows both generated and currentConstrainedOut by 1,
  // so the stable prefix offset is invariant throughout the loop.
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var sqlSteps: nat := 0;

  while sqlSteps < sqlBudget && insideConstrainedOut
    invariant 0 <= sqlSteps <= sqlBudget
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps + sqlSteps
    decreases sqlBudget - sqlSteps
  {
    var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
    sqlSteps := sqlSteps + 1;
    if next == eosToken {
      break;
    } else {
      var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
      if valid {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }

  steps := steps + sqlSteps;
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 120 {
      closeBudget := remaining;
    } else {
      closeBudget := 120;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

